input.command:
cd /home/runner/work/PlayGround/PlayGround && cat > package.json <<'EOF'
{
  "name": "little-ghost-cat",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vite --host 0.0.0.0 --port 3002",
    "build": "vite build",
    "preview": "vite preview --host 0.0.0.0 --port 3002"
  },
  "dependencies": {
    "three": "^0.187.0"
  },
  "devDependencies": {
    "vite": "^7.1.0"
  }
}
EOF
timeout 180 npm install 2>&1 | tail -5

input.content:
:root {
  --ink: #0a111b;
  --ink-2: #101c2a;
  --moon: #a9dcff;
  --moon-soft: #cfe9ff;
  --blue: #6fc7f5;
  --amber: #ffc36e;
  --candle: #ffb45e;
  --parchment: #f1e4cd;
  --parchment-dim: #c8bba5;
  --gold: #c7a86b;
  --panel: rgba(10, 17, 27, 0.84);
  --line: rgba(199, 168, 107, 0.32);
  --serif: "Cormorant Garamond", "Iowan Old Style", "Palatino Linotype", Georgia, serif;
  --sans: "Jost", "Avenir Next", "Segoe UI", sans-serif;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; width: 100%; height: 100%; overflow: hidden; background: #070d14; }
body { font-family: var(--sans); color: var(--parchment); -webkit-font-smoothing: antialiased; }
button { font-family: inherit; color: inherit; border: 0; background: none; cursor: pointer; }
button:focus-visible { outline: 1px solid var(--moon); outline-offset: 4px; }
.hidden { display: none !important; }

#app { position: fixed; inset: 0; overflow: hidden; }
#scene { display: block; width: 100%; height: 100%; touch-action: none; }

/* ---------- shared atmosphere ---------- */
.vignette {
  position: fixed; inset: 0; pointer-events: none; z-index: 20;
  background: radial-gradient(ellipse at 50% 45%, transparent 42%, rgba(2, 6, 12, 0.42) 80%, rgba(1, 3, 7, 0.72) 100%);
  mix-blend-mode: multiply;
}
.grain {
  position: fixed; inset: -50%; pointer-events: none; z-index: 21; opacity: 0.055;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  animation: grainShift 0.55s steps(2) infinite;
}
@keyframes grainShift { 0% { transform: translate(0,0); } 50% { transform: translate(2%, -1%); } 100% { transform: translate(-1%, 2%); } }
.fade { position: fixed; inset: 0; background: #03070c; opacity: 1; pointer-events: none; z-index: 60; transition: opacity 1.2s ease; }
.fade.clear { opacity: 0; }
.cinematic-bars { position: fixed; inset: 0; pointer-events: none; z-index: 30; }
.cinematic-bars i { position: absolute; left: 0; right: 0; height: 9vh; background: #02050a; transition: transform 1s cubic-bezier(.2,.8,.2,1); }
.cinematic-bars i.top { top: 0; transform: translateY(-100%); }
.cinematic-bars i.bottom { bottom: 0; transform: translateY(100%); }
.cinematic-bars.active i { transform: translateY(0); }

.eyebrow {
  font-family: var(--sans); font-size: 10px; font-weight: 400; letter-spacing: 0.36em;
  text-transform: uppercase; color: var(--gold); margin: 0;
}

/* ---------- loading ---------- */
.screen { position: fixed; inset: 0; z-index: 50; }
.loading-screen {
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 26px;
  background: radial-gradient(circle at 50% 45%, #13263a 0%, #0a1420 45%, #050a11 100%);
}
.loading-mark { margin-bottom: 4px; }
.ghost-mark { position: relative; width: 66px; height: 64px; filter: drop-shadow(0 0 18px rgba(111,199,245,.5)); }
.ghost-mark::before {
  content: ""; position: absolute; left: 7px; bottom: 0; width: 52px; height: 46px;
  border-radius: 50% 50% 42% 42% / 62% 62% 38% 38%;
  background: radial-gradient(ellipse at 40% 35%, rgba(214,245,255,.95), rgba(111,199,245,.72) 55%, rgba(55,128,180,.28) 100%);
}
.ghost-mark .ear { position: absolute; top: 0; width: 17px; height: 32px; background: linear-gradient(180deg, #c8efff, #79c9ef); clip-path: polygon(50% 0, 100% 100%, 0 100%); }
.ghost-mark .ear.left { left: 11px; transform: rotate(-12deg); }
.ghost-mark .ear.right { right: 11px; transform: rotate(12deg); }
.ghost-mark .eye { position: absolute; top: 26px; width: 12px; height: 15px; border-radius: 50%; }
.ghost-mark .eye.blue { left: 17px; background: #1e65b5; box-shadow: inset -2px 2px 0 rgba(255,255,255,.5); }
.ghost-mark .eye.amber { right: 17px; background: #ffc13b; box-shadow: inset -2px 2px 0 rgba(255,255,255,.4); }
.loading-bar { width: 160px; height: 1px; background: rgba(199,168,107,.18); overflow: hidden; }
.loading-bar i { display: block; width: 40%; height: 100%; background: linear-gradient(90deg, transparent, var(--gold), transparent); animation: loadSlide 1.5s ease-in-out infinite; }
@keyframes loadSlide { from { transform: translateX(-120%); } to { transform: translateX(360%); } }
.loading-screen .eyebrow { animation: breathe 3s ease-in-out infinite; }
@keyframes breathe { 0%,100% { opacity: .4 } 50% { opacity: .95 } }

/* ---------- title ---------- */
.title-screen { display: flex; flex-direction: column; align-items: center; justify-content: center; }
.title-screen::before {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(180deg, rgba(5,10,17,.18) 0%, rgba(5,10,17,.02) 35%, rgba(5,10,17,.5) 76%, rgba(4,8,14,.9) 100%);
}
.title-content { position: relative; text-align: center; padding: 0 24px; transform: translateY(-1vh); animation: titleIn 2.2s ease both; }
@keyframes titleIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
.title-content .eyebrow { color: #d8c090; margin-bottom: 24px; text-shadow: 0 0 20px rgba(0,0,0,.8); }
.title-content h1 {
  font-family: var(--serif); font-weight: 400; font-size: clamp(56px, 8.6vw, 126px); line-height: .82;
  letter-spacing: -0.015em; margin: 0; color: #eef7ff;
  text-shadow: 0 2px 40px rgba(98, 181, 233, .38), 0 1px 0 rgba(255,255,255,.16);
}
.title-content h1 em { font-style: italic; color: #b7e4ff; text-shadow: 0 0 50px rgba(111,199,245,.55); }
.title-rule { display: flex; align-items: center; justify-content: center; gap: 14px; margin: 28px 0 14px; color: var(--gold); }
.title-rule span { width: 72px; height: 1px; background: linear-gradient(90deg, transparent, rgba(199,168,107,.75)); }
.title-rule span:last-child { background: linear-gradient(90deg, rgba(199,168,107,.75), transparent); }
.title-rule i { font-style: normal; font-size: 12px; opacity: .9; }
.subtitle { font-family: var(--serif); font-style: italic; font-size: clamp(16px, 1.6vw, 21px); color: #c6d9e6; margin: 0 0 34px; letter-spacing: .02em; text-shadow: 0 2px 16px rgba(0,0,0,.7); }
.title-actions { display: flex; flex-direction: column; align-items: center; gap: 12px; }
.title-hint { position: relative; margin-top: 32px; font-size: 9.5px; letter-spacing: .2em; text-transform: uppercase; color: rgba(200,220,235,.5); }
.title-footer { position: absolute; bottom: 26px; display: flex; align-items: center; gap: 14px; z-index: 2; color: rgba(199,168,107,.55); font-family: var(--serif); font-style: italic; font-size: 13px; letter-spacing: .06em; }
.title-footer p { margin: 0; }
.title-footer span { font-size: 8px; opacity: .7; }

/* ---------- buttons ---------- */
.btn { position: relative; display: inline-flex; align-items: center; justify-content: center; min-width: 220px; padding: 15px 30px; font-size: 10px; letter-spacing: .26em; text-transform: uppercase; transition: all .35s ease; }
.btn-primary { color: #08131d; background: linear-gradient(180deg, #e7d3aa, #c7a86b); border: 1px solid rgba(255,240,205,.55); box-shadow: 0 8px 40px rgba(0,0,0,.36), inset 0 1px 0 rgba(255,255,255,.4); }
.btn-primary:hover { background: linear-gradient(180deg, #f7e6c0, #d8b97a); transform: translateY(-2px); box-shadow: 0 12px 44px rgba(0,0,0,.45), 0 0 30px rgba(199,168,107,.18); }
.btn-ghost { color: var(--parchment); border: 1px solid rgba(199,168,107,.42); background: rgba(9,15,24,.42); backdrop-filter: blur(8px); }
.btn-ghost:hover { border-color: rgba(230,203,150,.8); background: rgba(17,28,42,.6); }
.btn-text { color: rgba(212,225,235,.62); font-size: 9px; letter-spacing: .24em; padding: 10px; min-width: 0; }
.btn-text:hover { color: var(--parchment); }
.icon-btn { width: 38px; height: 38px; border: 1px solid rgba(199,168,107,.3); background: rgba(8,14,22,.46); color: rgba(234,222,199,.78); font-size: 12px; letter-spacing: 0; backdrop-filter: blur(6px); transition: all .3s; display: flex; align-items: center; justify-content: center; }
.icon-btn:hover { color: #fff; border-color: rgba(199,168,107,.7); }

/* ---------- HUD ---------- */
#hud { position: fixed; inset: 0; z-index: 25; pointer-events: none; }
#hud > * { pointer-events: none; }
#hud button { pointer-events: auto; }
.hud-top { position: absolute; top: max(22px, env(safe-area-inset-top)); left: 26px; right: 26px; display: flex; justify-content: space-between; align-items: flex-start; gap: 20px; }
.objective-panel { max-width: min(430px, 52vw); padding-left: 15px; border-left: 1px solid rgba(199,168,107,.5); text-shadow: 0 2px 12px rgba(0,0,0,.85); }
.hud-label { margin: 0 0 5px; font-size: 8.5px; letter-spacing: .32em; text-transform: uppercase; color: var(--gold); }
#objective-text { margin: 0; font-family: var(--serif); font-size: clamp(17px, 1.6vw, 22px); color: #f0e7d6; line-height: 1.15; }
.objective-sub { margin: 5px 0 0; font-size: 10px; letter-spacing: .06em; color: rgba(207,224,235,.58); }
.hud-top-right { display: flex; align-items: center; gap: 10px; }
.memory-counter { display: flex; align-items: center; gap: 7px; height: 38px; padding: 0 14px; border: 1px solid rgba(199,168,107,.26); background: rgba(8,14,22,.4); backdrop-filter: blur(8px); font-size: 11px; letter-spacing: .1em; color: #e8ddc8; text-shadow: 0 1px 5px #000; }
.mem-orb { width: 8px; height: 8px; border-radius: 50%; background: radial-gradient(circle at 35% 35%, #fff, #8dd8ff 45%, #2b8ec9); box-shadow: 0 0 10px rgba(121,208,255,.9); }
.mem-total { color: rgba(211,224,233,.48); font-size: 9px; letter-spacing: .14em; }
.room-banner { position: absolute; top: 15vh; left: 50%; transform: translateX(-50%); display: flex; align-items: center; gap: 16px; opacity: 0; transition: opacity 1.2s ease; text-align: center; }
.room-banner.visible { opacity: 1; }
.room-banner span { width: 40px; height: 1px; background: linear-gradient(90deg, transparent, rgba(199,168,107,.7)); }
.room-banner span:last-child { background: linear-gradient(90deg, rgba(199,168,107,.7), transparent); }
.room-banner p { margin: 0; font-family: var(--serif); font-style: italic; font-size: 19px; letter-spacing: .14em; color: rgba(236,242,247,.9); text-shadow: 0 2px 18px rgba(0,0,0,.8); }

.interact-prompt {
  position: absolute; left: 50%; bottom: 16vh; transform: translateX(-50%);
  display: flex; align-items: center; gap: 12px; padding: 10px 18px 10px 10px;
  background: rgba(7,12,19,.72); border: 1px solid rgba(199,168,107,.35); backdrop-filter: blur(10px);
  font-family: var(--serif); font-size: 17px; letter-spacing: .04em; color: #f3ead9; white-space: nowrap;
  box-shadow: 0 10px 40px rgba(0,0,0,.4); animation: promptIn .25s ease both;
}
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 6px); } to { opacity: 1; transform: translate(-50%, 0); } }
.keycap { display: inline-flex; align-items: center; justify-content: center; width: 30px; height: 30px; border: 1px solid rgba(199,168,107,.55); color: var(--gold); font-family: var(--sans); font-size: 10px; letter-spacing: .1em; background: rgba(199,168,107,.07); }
.controls-hint { position: absolute; left: 26px; bottom: max(20px, env(safe-area-inset-bottom)); display: flex; gap: 18px; font-size: 9px; letter-spacing: .13em; color: rgba(198,216,230,.4); text-transform: uppercase; transition: opacity .6s; }
.controls-hint b { color: rgba(232,219,194,.72); font-weight: 500; }
.toast-stack { position: absolute; left: 50%; bottom: 27vh; transform: translateX(-50%); display: flex; flex-direction: column; gap: 8px; align-items: center; }
.toast { padding: 10px 22px; background: rgba(7,13,21,.82); border: 1px solid rgba(199,168,107,.24); backdrop-filter: blur(10px); font-family: var(--serif); font-style: italic; font-size: 16px; color: #e9dfcc; text-align: center; animation: toastIn .5s ease both; box-shadow: 0 10px 30px rgba(0,0,0,.35); }
.toast.good { border-color: rgba(141,216,255,.35); color: #d9f1ff; }
.toast.key { border-color: rgba(255,195,110,.5); color: #ffe5bb; }
.toast.out { animation: toastOut .6s ease forwards; }
@keyframes toastIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-6px); } }

/* ---------- touch ---------- */
.touch-ui { position: absolute; inset: 0; display: none; }
.touch-ui.active { display: block; }
.joystick { position: absolute; left: 24px; bottom: max(30px, env(safe-area-inset-bottom)); width: 120px; height: 120px; border-radius: 50%; border: 1px solid rgba(199,168,107,.26); background: radial-gradient(circle, rgba(15,28,42,.42), rgba(5,10,16,.18)); pointer-events: auto; touch-action: none; }
.joystick-knob { position: absolute; left: 50%; top: 50%; width: 46px; height: 46px; margin: -23px; border-radius: 50%; border: 1px solid rgba(218,237,250,.55); background: radial-gradient(circle at 35% 30%, rgba(180,228,255,.65), rgba(86,160,207,.28)); box-shadow: 0 0 24px rgba(111,199,245,.22); }
.touch-actions { position: absolute; right: 22px; bottom: max(32px, env(safe-area-inset-bottom)); display: flex; align-items: flex-end; gap: 12px; pointer-events: auto; }
.touch-btn { display: flex; align-items: center; justify-content: center; border-radius: 50%; border: 1px solid rgba(199,168,107,.36); background: rgba(8,15,24,.5); backdrop-filter: blur(8px); font-size: 14px; letter-spacing: .08em; color: #e9e0d0; touch-action: none; }
.touch-btn.jump { width: 66px; height: 66px; font-size: 20px; }
.touch-btn.interact { width: 58px; height: 58px; font-size: 20px; color: #ffe6b6; border-color: rgba(255,195,110,.5); background: rgba(50,36,16,.42); }
.touch-btn.small { width: 50px; height: 50px; font-size: 8px; letter-spacing: .12em; text-transform: uppercase; }
.touch-btn.active { background: rgba(199,168,107,.28); border-color: rgba(255,225,175,.8); }
.mobile-look-zone { position: absolute; right: 0; top: 0; width: 58%; height: 100%; pointer-events: auto; touch-action: none; }
.touch-ui.active ~ .mobile-look-zone { display: block; }

/* ---------- overlays / cards ---------- */
.overlay { position: fixed; inset: 0; z-index: 40; display: flex; align-items: center; justify-content: center; padding: 28px; background: rgba(3,7,12,.58); backdrop-filter: blur(10px); animation: overlayIn .45s ease both; }
@keyframes overlayIn { from { opacity: 0; } to { opacity: 1; } }
.memory-card { background: rgba(3,7,12,.6); }
.memory-card-inner { display: grid; grid-template-columns: minmax(0, .9fr) minmax(0, 1.1fr); width: min(980px, 93vw); max-height: 88vh; background: linear-gradient(145deg, #101d2b, #0a121c 60%, #0c1620); border: 1px solid rgba(199,168,107,.34); box-shadow: 0 30px 100px rgba(0,0,0,.7); overflow: hidden; animation: cardRise .7s cubic-bezier(.16,.8,.24,1) both; }
@keyframes cardRise { from { opacity: 0; transform: translateY(22px) scale(.985); } to { opacity: 1; transform: translateY(0) scale(1); } }
.memory-art { position: relative; min-height: 420px; overflow: hidden; background: radial-gradient(circle at 50% 55%, #244d68, #101e2b 55%, #080e15); }
.memory-art::after { content: ""; position: absolute; inset: 0; background: linear-gradient(90deg, transparent 72%, rgba(9,17,26,.72)); }
.memory-art-glow { position: absolute; left: 50%; top: 50%; width: 60%; aspect-ratio: 1; transform: translate(-50%,-50%); border-radius: 50%; background: radial-gradient(circle, rgba(148,225,255,.32), rgba(64,154,206,.08) 50%, transparent 72%); filter: blur(10px); }
.memory-art-scene { position: absolute; inset: 0; opacity: .9; }
.memory-art-scene svg { width: 100%; height: 100%; }
.memory-copy { padding: clamp(28px, 4vw, 56px); display: flex; flex-direction: column; justify-content: center; overflow-y: auto; }
.memory-copy h2 { font-family: var(--serif); font-weight: 400; font-size: clamp(30px, 3vw, 44px); line-height: 1; margin: 10px 0 16px; color: #f4ecdc; }
.memory-rule { width: 48px; height: 1px; background: linear-gradient(90deg, var(--gold), transparent); margin-bottom: 18px; }
.memory-text { font-family: var(--serif); font-size: clamp(16px, 1.55vw, 20px); line-height: 1.62; color: #d8dde0; margin: 0 0 14px; }
.memory-sub { font-size: 10.5px; line-height: 1.7; letter-spacing: .06em; color: rgba(199,168,107,.72); margin: 0 0 28px; }
.memory-copy .btn { align-self: flex-start; min-width: 190px; }

/* journal */
.journal-screen { background: rgba(3,7,12,.66); }
.journal-card { width: min(1040px, 94vw); max-height: 88vh; display: flex; flex-direction: column; background: linear-gradient(150deg, #121c27, #0a121a); border: 1px solid rgba(199,168,107,.32); box-shadow: 0 30px 100px rgba(0,0,0,.72); }
.journal-card header { display: flex; align-items: flex-start; justify-content: space-between; padding: 26px 30px 20px; border-bottom: 1px solid rgba(199,168,107,.18); }
.journal-card h2 { font-family: var(--serif); font-weight: 400; font-size: 34px; margin: 5px 0 0; color: #f1e8d7; }
.journal-body { display: grid; grid-template-columns: 1.55fr .8fr; gap: 0; overflow: hidden; min-height: 0; }
.journal-body section { padding: 24px 30px 30px; overflow-y: auto; }
.journal-body aside { padding: 24px 26px 30px; border-left: 1px solid rgba(199,168,107,.14); background: rgba(6,11,18,.36); overflow-y: auto; }
.journal-body h3 { margin: 0 0 14px; font-size: 8.5px; letter-spacing: .3em; text-transform: uppercase; color: var(--gold); font-weight: 400; }
.journal-body aside h3:not(:first-child) { margin-top: 28px; }
.journal-memories { display: flex; flex-direction: column; gap: 5px; }
.journal-memory { display: grid; grid-template-columns: 28px 1fr; gap: 12px; padding: 12px 10px; border-bottom: 1px solid rgba(255,255,255,.05); }
.journal-memory .num { font-family: var(--serif); font-size: 14px; color: rgba(199,168,107,.6); padding-top: 2px; }
.journal-memory h4 { margin: 0 0 3px; font-family: var(--serif); font-size: 18px; font-weight: 500; color: #eadfca; }
.journal-memory p { margin: 0; font-size: 11.5px; line-height: 1.55; color: rgba(205,219,228,.52); }
.journal-memory.locked { opacity: .36; }
.journal-memory.locked h4 { color: rgba(220,225,228,.6); font-style: italic; }
.journal-items { display: flex; flex-wrap: wrap; gap: 7px; }
.journal-item { font-size: 9.5px; letter-spacing: .07em; padding: 8px 11px; border: 1px solid rgba(199,168,107,.28); color: #ddcba6; background: rgba(199,168,107,.05); }
.journal-empty { font-family: var(--serif); font-style: italic; font-size: 14px; color: rgba(204,216,224,.36); }
.journal-places { display: flex; flex-direction: column; gap: 5px; font-family: var(--serif); font-size: 15px; color: rgba(225,232,236,.62); }
.journal-places span.visited { color: rgba(240,232,217,.9); }
.journal-tip { margin-top: 28px; padding: 14px; border: 1px solid rgba(199,168,107,.18); background: rgba(199,168,107,.035); display: flex; gap: 10px; }
.journal-tip span { color: var(--gold); font-size: 11px; }
.journal-tip p { margin: 0; font-family: var(--serif); font-style: italic; font-size: 14px; line-height: 1.45; color: rgba(222,228,230,.62); }

/* pause / settings */
.pause-card, .settings-card { width: min(460px, 92vw); background: linear-gradient(150deg, #111d29, #0a121b); border: 1px solid rgba(199,168,107,.32); padding: 38px 40px; box-shadow: 0 30px 100px rgba(0,0,0,.72); }
.pause-card h2, .settings-card h2 { font-family: var(--serif); font-weight: 400; font-size: 46px; margin: 6px 0 26px; color: #f1e8d7; }
.pause-actions { display: flex; flex-direction: column; gap: 9px; }
.pause-actions .btn { width: 100%; }
.save-note { margin: 16px 0 0; min-height: 16px; font-family: var(--serif); font-style: italic; font-size: 14px; color: rgba(167,216,245,.74); text-align: center; }
.settings-card { width: min(560px, 94vw); }
.settings-card header { display: flex; justify-content: space-between; align-items: flex-start; }
.settings-card h2 { margin-bottom: 24px; }
.settings-grid { display: flex; flex-direction: column; gap: 20px; }
.setting { display: grid; grid-template-columns: 1fr 145px 40px; align-items: center; gap: 14px; font-size: 11px; letter-spacing: .06em; color: rgba(225,232,236,.8); }
.setting input[type="range"] { appearance: none; -webkit-appearance: none; height: 2px; background: rgba(199,168,107,.3); outline: none; }
.setting input[type="range"]::-webkit-slider-thumb { -webkit-appearance: none; width: 12px; height: 12px; border-radius: 50%; background: #ddc794; box-shadow: 0 0 10px rgba(199,168,107,.4); cursor: pointer; }
.setting em { font-style: normal; font-size: 10px; color: rgba(199,168,107,.8); text-align: right; }
.setting.toggle { grid-template-columns: 1fr 46px; }
.setting.toggle input { display: none; }
.setting.toggle i { width: 42px; height: 22px; border-radius: 12px; border: 1px solid rgba(199,168,107,.3); background: rgba(0,0,0,.3); position: relative; transition: .3s; cursor: pointer; }
.setting.toggle i::after { content: ""; position: absolute; top: 3px; left: 3px; width: 14px; height: 14px; border-radius: 50%; background: rgba(210,220,228,.55); transition: .3s; }
.setting.toggle input:checked + i { background: rgba(199,168,107,.24); border-color: rgba(199,168,107,.65); }
.setting.toggle input:checked + i::after { transform: translateX(20px); background: #f2dfb6; box-shadow: 0 0 8px rgba(199,168,107,.5); }
.settings-note { margin: 24px 0; font-size: 9.5px; letter-spacing: .05em; color: rgba(200,214,224,.36); }
.settings-card .btn-primary { width: 100%; }

/* puzzle */
.puzzle-card { width: min(620px, 94vw); background: radial-gradient(circle at 50% 0%, #18293a, #0a121b 70%); border: 1px solid rgba(199,168,107,.32); padding: 40px; text-align: center; box-shadow: 0 30px 100px rgba(0,0,0,.72); }
.puzzle-card h2 { font-family: var(--serif); font-weight: 400; font-size: 38px; margin: 8px 0 10px; color: #f1e8d7; }
.puzzle-clue { font-family: var(--serif); font-style: italic; font-size: 17px; color: rgba(205,224,238,.64); margin: 0 auto 28px; max-width: 420px; }
.puzzle-keys { display: flex; justify-content: center; gap: 12px; margin-bottom: 22px; }
.puzzle-key { width: 72px; height: 104px; border-radius: 4px 4px 8px 8px; border: 1px solid rgba(255,255,255,.16); background: linear-gradient(180deg, #e8dcc4, #b9a887); color: #27333c; font-family: var(--serif); font-size: 13px; display: flex; flex-direction: column; align-items: center; justify-content: flex-end; padding-bottom: 12px; gap: 5px; transition: all .25s; box-shadow: 0 5px 0 #6e614c, 0 10px 18px rgba(0,0,0,.4); }
.puzzle-key span { font-size: 20px; }
.puzzle-key:hover { transform: translateY(-3px); box-shadow: 0 8px 0 #6e614c, 0 14px 22px rgba(0,0,0,.45); }
.puzzle-key.pressed { transform: translateY(3px); box-shadow: 0 2px 0 #6e614c, 0 4px 10px rgba(0,0,0,.4); background: linear-gradient(180deg, #bfe7ff, #7ec2e8); }
.puzzle-key.wrong { animation: shake .4s ease; }
@keyframes shake { 0%,100% { transform: translateX(0) } 25% { transform: translateX(-5px) } 75% { transform: translateX(5px) } }
.puzzle-feedback { min-height: 24px; font-family: var(--serif); font-style: italic; font-size: 15px; color: rgba(173,218,244,.75); margin-bottom: 14px; }
.puzzle-card .btn { margin-top: 4px; }

/* ending */
.ending-screen { background: radial-gradient(circle at 50% 40%, #203d52 0%, #0b1722 45%, #050a10 100%); }
.ending-inner { text-align: center; max-width: 680px; animation: cardRise 1.4s ease both; }
.ending-inner h1 { font-family: var(--serif); font-weight: 400; font-size: clamp(52px, 7vw, 92px); line-height: .88; margin: 24px 0 26px; color: #eef8ff; text-shadow: 0 0 60px rgba(128,205,245,.25); }
.ending-inner h1 em { font-style: italic; color: #bfe6ff; }
.ending-text { font-family: var(--serif); font-size: 19px; line-height: 1.7; color: rgba(218,231,239,.78); margin: 0 auto 24px; max-width: 540px; }
.ending-stats { display: flex; justify-content: center; gap: 36px; margin-bottom: 34px; }
.ending-stat { display: flex; flex-direction: column; gap: 5px; }
.ending-stat b { font-family: var(--serif); font-size: 26px; font-weight: 400; color: #e9d5aa; }
.ending-stat span { font-size: 8px; letter-spacing: .26em; text-transform: uppercase; color: rgba(199,168,107,.6); }
.ending-actions { display: flex; flex-direction: column; gap: 10px; align-items: center; }

/* intro */
.intro-screen { background: rgba(3,7,12,.4); backdrop-filter: blur(3px); }
.intro-inner { max-width: 520px; text-align: center; padding: 0 24px; animation: cardRise 1.2s ease both; }
.intro-inner h2 { font-family: var(--serif); font-weight: 400; font-size: clamp(32px, 4vw, 46px); line-height: 1.06; color: #eef6fd; margin: 18px 0 18px; }
.intro-inner p:not(.eyebrow) { font-family: var(--serif); font-size: 18px; line-height: 1.65; color: rgba(221,232,240,.7); margin: 0 0 30px; }

@media (max-width: 760px) {
  .hud-top { left: 16px; right: 16px; top: 16px; }
  .objective-panel { max-width: 58vw; padding-left: 10px; }
  #objective-text { font-size: 15px; }
  .objective-sub { display: none; }
  .memory-counter { padding: 0 10px; height: 34px; font-size: 10px; }
  .mem-total { display: none; }
  .controls-hint { display: none; }
  .interact-prompt { bottom: 24vh; font-size: 15px; }
  .journal-body { grid-template-columns: 1fr; overflow-y: auto; }
  .journal-body aside { border-left: 0; border-top: 1px solid rgba(199,168,107,.14); }
  .journal-card { max-height: 90vh; }
  .memory-card-inner { grid-template-columns: 1fr; max-height: 88vh; overflow-y: auto; }
  .memory-art { min-height: 210px; }
  .memory-card-inner .memory-copy { padding: 24px; }
  .title-content h1 { font-size: 62px; }
  .title-footer { display: none; }
  .setting { grid-template-columns: 1fr 100px 34px; gap: 10px; }
  .pause-card, .settings-card { padding: 28px 24px; }
  .puzzle-card { padding: 30px 20px; }
  .puzzle-key { width: 58px; height: 88px; }
  .title-hint { display: none; }
  .ending-stats { gap: 22px; }
}
@media (max-height: 620px) {
  .title-content h1 { font-size: clamp(44px, 8vh, 80px); }
  .title-content .eyebrow { margin-bottom: 14px; }
  .subtitle { margin-bottom: 22px; }
  .title-hint { display: none; }
  .memory-art { min-height: 300px; }
}

import * as THREE from 'three';

let rngState = 1337;
export function rand() {
  rngState = (rngState * 1664525 + 1013904223) % 4294967296;
  return rngState / 4294967296;
}
export function resetRand(seed = 1337) { rngState = seed; }

function canvas(w = 512, h = 512) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  return [c, c.getContext('2d')];
}

function tex(c, repeat = [1, 1], srgb = true) {
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(repeat[0], repeat[1]);
  t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  t.anisotropy = 4;
  return t;
}

function noise(ctx, w, h, amount = 14, alpha = 0.05) {
  const img = ctx.getImageData(0, 0, w, h);
  for (let i = 0; i < img.data.length; i += 4) {
    const n = (Math.random() - 0.5) * amount;
    img.data[i] += n; img.data[i + 1] += n; img.data[i + 2] += n;
  }
  ctx.putImageData(img, 0, 0);
  if (alpha > 0) {
    ctx.globalAlpha = alpha;
    for (let i = 0; i < 900; i++) {
      ctx.fillStyle = Math.random() > 0.5 ? '#000' : '#fff';
      ctx.fillRect(Math.random() * w, Math.random() * h, 1, 1);
    }
    ctx.globalAlpha = 1;
  }
}

export function woodFloor(light = false) {
  const [c, ctx] = canvas(512, 512);
  const base = light ? ['#7d512f', '#8d5d37', '#6d4528', '#94653e'] : ['#4a2e1c', '#553522', '#3f2718', '#5e3c25'];
  ctx.fillStyle = base[0]; ctx.fillRect(0, 0, 512, 512);
  const plankH = 64;
  for (let row = 0; row < 8; row++) {
    const offset = (row % 2) * 128;
    for (let col = -1; col < 3; col++) {
      const x = offset + col * 256, y = row * plankH;
      const colr = base[Math.floor(rand() * base.length)];
      ctx.fillStyle = colr;
      ctx.fillRect(x + 1, y + 1, 254, plankH - 2);
      const grad = ctx.createLinearGradient(x, y, x, y + plankH);
      grad.addColorStop(0, 'rgba(255,220,180,.07)');
      grad.addColorStop(0.5, 'rgba(0,0,0,0)');
      grad.addColorStop(1, 'rgba(0,0,0,.16)');
      ctx.fillStyle = grad; ctx.fillRect(x + 1, y + 1, 254, plankH - 2);
      for (let g = 0; g < 7; g++) {
        ctx.strokeStyle = `rgba(${Math.random() > .5 ? '25,12,5' : '220,170,110'},${0.04 + rand() * 0.05})`;
        ctx.lineWidth = 0.7 + rand();
        ctx.beginPath();
        const gy = y + 8 + rand() * (plankH - 16);
        ctx.moveTo(x + 8, gy);
        ctx.bezierCurveTo(x + 70, gy + rand() * 5 - 2, x + 180, gy - rand() * 4, x + 248, gy + rand() * 4 - 2);
        ctx.stroke();
      }
      ctx.fillStyle = 'rgba(15,7,2,.28)'; ctx.fillRect(x, y, 2, plankH);
    }
  }
  noise(ctx, 512, 512, 10, 0.022);
  return tex(c, [1, 1]);
}

export function woodPanel(dark = false) {
  const [c, ctx] = canvas(256, 256);
  const g = ctx.createLinearGradient(0, 0, 0, 256);
  g.addColorStop(0, dark ? '#2c1a10' : '#4a2c1b');
  g.addColorStop(0.5, dark ? '#3b2416' : '#5c3922');
  g.addColorStop(1, dark ? '#24140c' : '#3d2415');
  ctx.fillStyle = g; ctx.fillRect(0, 0, 256, 256);
  for (let i = 0; i < 26; i++) {
    ctx.strokeStyle = `rgba(${dark ? '10,5,2' : '25,12,5'},${0.06 + rand() * 0.08})`;
    ctx.lineWidth = .6 + rand() * 1.4;
    ctx.beginPath();
    const y = rand() * 256;
    ctx.moveTo(0, y);
    ctx.bezierCurveTo(80, y + rand() * 8 - 4, 170, y - rand() * 7, 256, y + rand() * 6);
    ctx.stroke();
  }
  noise(ctx, 256, 256, 10, 0.02);
  return tex(c, [1, 1]);
}

export function wallpaper(bg = '#1c3a37', accent = '#8e6f3e', style = 0) {
  const [c, ctx] = canvas(512, 512);
  ctx.fillStyle = bg; ctx.fillRect(0, 0, 512, 512);
  const g = ctx.createLinearGradient(0, 0, 0, 512);
  g.addColorStop(0, 'rgba(255,255,255,.035)');
  g.addColorStop(1, 'rgba(0,0,0,.14)');
  ctx.fillStyle = g; ctx.fillRect(0, 0, 512, 512);
  ctx.strokeStyle = accent; ctx.fillStyle = accent;
  if (style === 0) {
    for (let y = 0; y < 512; y += 128) {
      for (let x = 0; x < 512; x += 128) {
        const ox = (Math.floor(y / 128) % 2) * 64;
        ctx.save(); ctx.translate(x + ox, y + 64);
        ctx.globalAlpha = 0.16;
        ctx.beginPath();
        for (let i = 0; i < 8; i++) {
          const a = (i / 8) * Math.PI * 2;
          const r = i % 2 ? 12 : 34;
          ctx.lineTo(Math.cos(a) * r, Math.sin(a) * r * 1.4);
        }
        ctx.closePath(); ctx.stroke();
        ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI * 2); ctx.fill();
        ctx.globalAlpha = 0.09;
        ctx.beginPath(); ctx.ellipse(0, 46, 3, 14, 0, 0, Math.PI * 2); ctx.fill();
        ctx.restore();
      }
    }
  } else if (style === 1) {
    for (let y = 0; y < 512; y += 64) {
      for (let x = 0; x < 512; x += 64) {
        ctx.globalAlpha = 0.1;
        ctx.beginPath();
        ctx.arc(x + 32, y + 32, 15, 0, Math.PI * 2);
        ctx.stroke();
        ctx.beginPath(); ctx.arc(x + 32, y + 32, 4, 0, Math.PI * 2); ctx.fill();
      }
    }
  } else {
    ctx.globalAlpha = 0.09;
    for (let x = 0; x < 512; x += 32) {
      ctx.fillRect(x, 0, 3, 512);
    }
    for (let y = 0; y < 512; y += 96) {
      ctx.fillRect(0, y, 512, 4);
    }
  }
  ctx.globalAlpha = 1;
  noise(ctx, 512, 512, 8, 0.02);
  return tex(c, [1, 1]);
}

export function rug(main = '#6b2630', accent = '#c9a463', border = '#263a4f', ornate = true) {
  const [c, ctx] = canvas(512, 512);
  ctx.fillStyle = border; ctx.fillRect(0, 0, 512, 512);
  ctx.fillStyle = accent; ctx.fillRect(16, 16, 480, 480);
  ctx.fillStyle = main; ctx.fillRect(28, 28, 456, 456);
  ctx.strokeStyle = accent; ctx.globalAlpha = 0.7; ctx.lineWidth = 2;
  ctx.strokeRect(42, 42, 428, 428);
  if (ornate) {
    ctx.globalAlpha = 0.28;
    for (let i = 0; i < 8; i++) {
      ctx.save(); ctx.translate(256, 256); ctx.rotate(i * Math.PI / 4);
      ctx.beginPath();
      for (let j = 0; j < 12; j++) {
        const a = (j / 12) * Math.PI * 2;
        const r = j % 2 ? 26 : 150;
        ctx.lineTo(Math.cos(a) * r * .55, Math.sin(a) * r);
      }
      ctx.closePath(); ctx.stroke(); ctx.restore();
    }
    ctx.globalAlpha = 0.38;
    ctx.beginPath(); ctx.arc(256, 256, 58, 0, Math.PI * 2); ctx.stroke();
    ctx.beginPath(); ctx.arc(256, 256, 70, 0, Math.PI * 2); ctx.stroke();
    ctx.beginPath(); ctx.arc(256, 256, 12, 0, Math.PI * 2); ctx.fill();
  }
  ctx.globalAlpha = 1;
  for (let i = 0; i < 60; i++) {
    ctx.fillStyle = `rgba(0,0,0,${rand() * .08})`;
    ctx.fillRect(rand() * 512, rand() * 512, rand() * 30 + 4, 1.5);
  }
  noise(ctx, 512, 512, 16, 0.04);
  return tex(c, [1, 1]);
}

export function stone(bg = '#3c4146', block = '#5b5f63', moss = true) {
  const [c, ctx] = canvas(512, 512);
  ctx.fillStyle = '#23272a'; ctx.fillRect(0, 0, 512, 512);
  const rows = 8;
  for (let r = 0; r < rows; r++) {
    const h = 512 / rows;
    const off = (r % 2) * 55;
    for (let x = -120; x < 512; x += 110) {
      const w = 100 + rand() * 20;
      const shade = 0.8 + rand() * .4;
      const col = new THREE.Color(block).multiplyScalar(shade);
      ctx.fillStyle = `#${col.getHexString()}`;
      ctx.fillRect(x + off + 3, r * h + 3, w - 6, h - 6);
      ctx.strokeStyle = 'rgba(255,255,255,.045)';
      ctx.strokeRect(x + off + 5, r * h + 5, w - 10, h - 10);
    }
  }
  if (moss) {
    for (let i = 0; i < 80; i++) {
      ctx.fillStyle = `rgba(${60 + rand() * 30},${80 + rand() * 30},${40},${.04 + rand() * .07})`;
      ctx.beginPath(); ctx.arc(rand() * 512, rand() * 512, rand() * 20 + 3, 0, Math.PI * 2); ctx.fill();
    }
  }
  noise(ctx, 512, 512, 22, 0.05);
  return tex(c, [1, 1]);
}

export function tile(base = '#d8cbb2', line = '#a79779') {
  const [c, ctx] = canvas(256, 256);
  ctx.fillStyle = line; ctx.fillRect(0, 0, 256, 256);
  for (let y = 0; y < 4; y++) for (let x = 0; x < 4; x++) {
    const shade = 0.88 + rand() * .18;
    const col = new THREE.Color(base).multiplyScalar(shade);
    ctx.fillStyle = `#${col.getHexString()}`;
    ctx.fillRect(x * 64 + 2, y * 64 + 2, 60, 60);
  }
  noise(ctx, 256, 256, 8, 0.02);
  return tex(c, [1, 1]);
}

export function fabric(base = '#42566b', line = '#5f7a92') {
  const [c, ctx] = canvas(256, 256);
  ctx.fillStyle = base; ctx.fillRect(0, 0, 256, 256);
  ctx.strokeStyle = line; ctx.globalAlpha = .28;
  for (let i = 0; i < 256; i += 4) {
    ctx.beginPath(); ctx.moveTo(i, 0); ctx.lineTo(i, 256); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(0, i); ctx.lineTo(256, i); ctx.stroke();
  }
  ctx.globalAlpha = 1;
  noise(ctx, 256, 256, 12, 0.02);
  return tex(c, [1, 1]);
}

export function marble(base = '#bfc4c6', vein = '#6d7a80') {
  const [c, ctx] = canvas(256, 256);
  ctx.fillStyle = base; ctx.fillRect(0, 0, 256, 256);
  for (let i = 0; i < 14; i++) {
    ctx.strokeStyle = `rgba(90,105,112,${.08 + rand() * .12})`;
    ctx.lineWidth = .7 + rand() * 1.6;
    ctx.beginPath();
    let x = rand() * 256, y = 0;
    ctx.moveTo(x, y);
    for (let j = 0; j < 8; j++) {
      x += (rand() - .5) * 40; y += 34;
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
  noise(ctx, 256, 256, 6, 0.01);
  return tex(c, [1, 1]);
}

export function moonWindow(arch = false) {
  const [c, ctx] = canvas(512, 768);
  const g = ctx.createLinearGradient(0, 0, 0, 768);
  g.addColorStop(0, '#081726'); g.addColorStop(.55, '#123551'); g.addColorStop(1, '#1b4c63');
  ctx.fillStyle = g; ctx.fillRect(0, 0, 512, 768);
  const mg = ctx.createRadialGradient(350, 160, 10, 350, 160, 240);
  mg.addColorStop(0, 'rgba(220,245,255,.85)');
  mg.addColorStop(.18, 'rgba(160,215,255,.4)');
  mg.addColorStop(1, 'rgba(80,150,210,0)');
  ctx.fillStyle = mg; ctx.fillRect(0, 0, 512, 768);
  ctx.fillStyle = '#eaf9ff';
  ctx.beginPath(); ctx.arc(350, 160, 34, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = 'rgba(200,225,235,.28)';
  ctx.beginPath(); ctx.arc(362, 150, 9, 0, Math.PI * 2); ctx.fill();
  ctx.beginPath(); ctx.arc(338, 172, 6, 0, Math.PI * 2); ctx.fill();
  // distant trees
  ctx.fillStyle = 'rgba(5,18,26,.75)';
  for (let i = 0; i < 18; i++) {
    const x = rand() * 512, w = 20 + rand() * 50, h = 100 + rand() * 200;
    ctx.beginPath(); ctx.moveTo(x - w, 768); ctx.lineTo(x, 768 - h); ctx.lineTo(x + w / 2, 768); ctx.fill();
  }
  // rain
  ctx.strokeStyle = 'rgba(190,225,248,.18)'; ctx.lineWidth = 1;
  for (let i = 0; i < 180; i++) {
    const x = rand() * 512, y = rand() * 768, l = 8 + rand() * 26;
    ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x - 2, y + l); ctx.stroke();
  }
  // mullions
  ctx.fillStyle = 'rgba(14,10,8,.92)';
  ctx.fillRect(250, 0, 12, 768);
  ctx.fillRect(0, 300, 512, 12);
  ctx.fillRect(0, 560, 512, 10);
  ctx.fillRect(0, 0, 512, 14);
  ctx.fillRect(0, 0, 14, 768);
  ctx.fillRect(498, 0, 14, 768);
  if (arch) {
    ctx.globalCompositeOperation = 'destination-in';
    ctx.beginPath();
    ctx.moveTo(0, 768); ctx.lineTo(0, 120);
    ctx.quadraticCurveTo(256, -120, 512, 120);
    ctx.lineTo(512, 768); ctx.closePath(); ctx.fill();
    ctx.globalCompositeOperation = 'source-over';
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}

export function painting(kind = 0) {
  const [c, ctx] = canvas(384, 480);
  const g = ctx.createLinearGradient(0, 0, 0, 480);
  if (kind === 0) { g.addColorStop(0, '#1f3348'); g.addColorStop(.6, '#4b6577'); g.addColorStop(1, '#232a2c'); }
  else if (kind === 1) { g.addColorStop(0, '#3b2239'); g.addColorStop(.7, '#7d4a3b'); g.addColorStop(1, '#241a18'); }
  else if (kind === 2) { g.addColorStop(0, '#20342a'); g.addColorStop(.7, '#58684a'); g.addColorStop(1, '#1b2218'); }
  else { g.addColorStop(0, '#44352a'); g.addColorStop(.6, '#8b6d4a'); g.addColorStop(1, '#2a2117'); }
  ctx.fillStyle = g; ctx.fillRect(0, 0, 384, 480);
  // painterly landscape / interiors
  if (kind === 0) {
    ctx.fillStyle = 'rgba(238,233,210,.6)';
    ctx.beginPath(); ctx.arc(290, 108, 28, 0, Math.PI * 2); ctx.fill();
    for (let i = 0; i < 9; i++) {
      const x = 20 + rand() * 340, h = 100 + rand() * 200;
      ctx.fillStyle = `rgba(12,25,30,${.4 + rand() * .3})`;
      ctx.beginPath(); ctx.moveTo(x - 40, 400); ctx.lineTo(x, 400 - h); ctx.lineTo(x + 40, 400); ctx.fill();
    }
    ctx.fillStyle = 'rgba(155,170,162,.28)'; ctx.fillRect(0, 380, 384, 100);
    ctx.strokeStyle = 'rgba(230,220,190,.3)'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(110, 390); ctx.lineTo(130, 410); ctx.lineTo(126, 470); ctx.stroke();
  } else if (kind === 1) {
    // little cat silhouette
    ctx.fillStyle = 'rgba(25,17,12,.8)';
    ctx.beginPath(); ctx.ellipse(220, 390, 70, 46, 0, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(258, 330, 38, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.moveTo(232, 305); ctx.lineTo(240, 260); ctx.lineTo(258, 298); ctx.fill();
    ctx.beginPath(); ctx.moveTo(268, 298); ctx.lineTo(286, 258); ctx.lineTo(291, 306); ctx.fill();
    ctx.strokeStyle = 'rgba(25,17,12,.6)'; ctx.lineWidth = 8;
    ctx.beginPath(); ctx.moveTo(160, 400); ctx.bezierCurveTo(90, 330, 140, 280, 100, 240); ctx.stroke();
    ctx.fillStyle = 'rgba(248,214,150,.55)';
    ctx.beginPath(); ctx.arc(160, 180, 50, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = 'rgba(25,17,12,.4)';
    ctx.fillRect(0, 430, 384, 50);
  } else if (kind === 2) {
    ctx.fillStyle = 'rgba(30,32,22,.5)';
    for (let i = 0; i < 70; i++) {
      const x = rand() * 384, y = 240 + rand() * 240;
      ctx.beginPath(); ctx.arc(x, y, 3 + rand() * 22, 0, Math.PI * 2); ctx.fill();
    }
    ctx.fillStyle = 'rgba(245,216,160,.34)';
    ctx.beginPath(); ctx.arc(180, 200, 80, 0, Math.PI * 2); ctx.fill();
  } else {
    ctx.fillStyle = 'rgba(20,14,10,.7)';
    ctx.fillRect(40, 300, 304, 12);
    ctx.fillRect(60, 312, 8, 100);
    ctx.fillRect(316, 312, 8, 100);
    ctx.fillStyle = 'rgba(240,207,145,.55)';
    ctx.beginPath(); ctx.arc(100, 260, 22, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = 'rgba(20,14,10,.55)';
    ctx.fillRect(200, 230, 80, 80);
  }
  // varnish/cracks
  ctx.globalAlpha = .12;
  for (let i = 0; i < 22; i++) {
    ctx.strokeStyle = '#000'; ctx.lineWidth = .6;
    ctx.beginPath(); ctx.moveTo(rand() * 384, rand() * 480); ctx.lineTo(rand() * 384, rand() * 480); ctx.stroke();
  }
  ctx.globalAlpha = .25;
  const vg = ctx.createRadialGradient(192, 240, 50, 192, 240, 320);
  vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(0,0,0,.7)');
  ctx.fillStyle = vg; ctx.fillRect(0, 0, 384, 480);
  ctx.globalAlpha = 1;
  noise(ctx, 384, 480, 8, 0.015);
  return tex(c, [1, 1]);
}

