  kitchenWall: { bg: '#8d8066', accent: '#c7b68f', style: 2 },
  bedroomWall: { bg: '#3c3447', accent: '#9f8c6b', style: 1 },
  childWall: { bg: '#2d4252', accent: '#a7b0a0', style: 1 },
