    m.group.add(wire);
    const bulb = new THREE.Mesh(new THREE.SphereGeometry(0.08, 10, 8), new THREE.MeshBasicMaterial({ color: 0xffc47f }));
    bulb.position.set(12 + i * 4, Y + 2.5, -2); m.group.add(bulb);
