  m.walkables.push({ type: 'rect', minX: -19, maxX: 19, minZ: -32.5, maxZ: -10.2, y: 0, tag: 'garden' });

  // winding stepping-stone path
  const pathMat = new THREE.MeshStandardMaterial({ map: M.stone.map, color: 0x8a8f88, roughness: 0.9 });
