  m.colliders.push({ minX: 12.2, maxX: 14.0, minZ: z2 - 0.4, maxZ: z2 + 0.2, minY: 0, maxY: 2.2 });

  // shelf + key
  const shelf = m.addBox(2.0, 0.08, 0.4, M.woodPale, 13.2, 1.2, z1 + 0.3);
  const legs = 4;
  // key
