182:   addDoorFrame(x, z, width, height, rotY, mat, y = 0) {
183:     const frame = new THREE.Group();
184:     frame.position.set(x, y, z);
185:     frame.rotation.y = rotY;
186:     frame.add(F.box(width + 0.24, 0.18, 0.22, mat, 0, height + 0.09, 0));
187:     for (const s of [-1, 1]) frame.add(F.box(0.16, height + 0.18, 0.22, mat, s * (width / 2 + 0.04), (height + 0.18) / 2, 0));
188:     this.group.add(frame);
189:     return frame;
190:   }
