192:   addDoor({ id, x, z, width = 2.0, height = 2.7, rotY = 0, label = 'Door', locked = false, key = null, lockedText = 'It is locked.', open = false, swing = 1, mat, hinge = -1, y = 0, wallThick = 0.3 }) {
193:     if (!mat) mat = this.M.panelDark;
194:     const fx = x + Math.cos(rotY) * hinge * width / 2;
195:     const fz = z - Math.sin(rotY) * hinge * width / 2;
196:     this.addDoorFrame(fx, fz, width, height, rotY, this.M.woodDark, y);
197:     const pivot = new THREE.Group();
198:     pivot.position.set(x, y, z);
199:     pivot.rotation.y = rotY;
200:     const panel = new THREE.Group();
201:     // panel extends from hinge to +width on local X; hinge = -1 means pivot at left edge
202:     const dir = hinge;
203:     // decorative paneled door
204:     const doorMesh = F.box(width, height, 0.11, mat, dir * width / 2, height / 2, 0, 0.01);
205:     panel.add(doorMesh);
206:     for (let i = 0; i < 3; i++) {
207:       panel.add(F.box(width * 0.36, height * 0.2, 0.03, this.M.woodDark, dir * (width * 0.27 + (i % 2) * width * 0.2), height * (0.22 + i * 0.27), 0.065));
208:       panel.add(F.box(width * 0.36, height * 0.2, 0.03, this.M.woodDark, dir * (width * 0.73 - (i % 2) * width * 0.2), height * (0.22 + i * 0.27), 0.065));
209:     }
210:     // knob
211:     const knob = new THREE.Mesh(new THREE.SphereGeometry(0.055, 10, 8), this.M.brass);
212:     knob.position.set(dir * (width - 0.18), height * 0.46, 0.12);
213:     panel.add(knob);
214:     const escutcheon = F.box(0.06, 0.12, 0.02, this.M.brass, dir * (width - 0.18), height * 0.42, 0.115);
215:     panel.add(escutcheon);
216:     pivot.add(panel);
217:     pivot.userData.isDoor = true;
218:     pivot.userData.doorId = id;
219:     this.group.add(pivot);
220:     pivot.traverse(o => { if (o.isMesh) this.meshes.push(o); });
221: 
222:     const ex = x + Math.cos(rotY) * width * hinge;
223:     const ez = z - Math.sin(rotY) * width * hinge;
224:     const c = {
225:       minX: Math.min(x, ex) - 0.14, maxX: Math.max(x, ex) + 0.14,
226:       minZ: Math.min(z, ez) - 0.14, maxZ: Math.max(z, ez) + 0.14,
227:       minY: y, maxY: y + height + 0.2,
228:     };
229:     this.colliders.push(c);
230: 
231:     const door = {
232:       id, pivot, panel, width, height, rotY, label, locked, key, lockedText,
233:       open: false, target: 0, current: 0, swing, hinge, collider: c, x, z, y,
234:       doorMesh,
235:     };
236:     pivot.rotation.y = rotY;
237:     this.doors.set(id, door);
238:     const openRot = rotY + swing * hinge * -1 * Math.PI * 0.52;
239:     door.openRot = rotY + swing * Math.PI * 0.54 * hinge;
240:     if (open) this.setDoorOpen(id, true, true);
241:     this.addInteractive(`door_${id}`, label, pivot, x, z, y + 1, Math.max(2.2, width * 1.1), { type: 'door', doorId: id });
242:     return door;
243:   }
