245:   setDoorOpen(id, state, instant = false) {
246:     const d = this.doors.get(id);
247:     if (!d) return;
248:     d.open = state;
249:     d.target = state ? d.openRot : d.rotY;
250:     if (instant) {
251:       d.current = d.target;
252:       d.pivot.rotation.y = d.target;
253:       d.collider.minY = state ? 999 : d.y;
254:       d.collider.maxY = state ? 999.1 : d.y + d.height + 0.2;
255:     } else {
256:       d.collider.minY = state ? 999 : d.y;
257:       d.collider.maxY = state ? 999.1 : d.y + d.height + 0.2;
258:     }
259:     const int = this.interactives.find(i => i.id === `door_${id}`);
260:     if (int) int.label = state ? 'Close door' : (d.locked ? 'Try the door' : 'Open door');
261:   }
