503:   // flicker / animations
504:   update(dt, elapsed) {
505:     this.time += dt;
506:     for (const d of this.doors.values()) {
507:       if (Math.abs(d.current - d.target) > 0.001) {
508:         const speed = 2.8;
509:         d.current += (d.target - d.current) * Math.min(1, dt * speed);
510:         if (Math.abs(d.current - d.target) < 0.002) d.current = d.target;
511:         d.pivot.rotation.y = d.current;
512:       }
513:     }
514:     if (this.dust) {
515:       const { pos, seed, count } = this.dustData;
516:       for (let i = 0; i < count; i++) {
517:         pos[i * 3] += Math.sin(elapsed * 0.16 + seed[i]) * 0.0016;
518:         pos[i * 3 + 1] += Math.sin(elapsed * 0.23 + seed[i] * 2) * 0.0014;
519:         pos[i * 3 + 2] += Math.cos(elapsed * 0.12 + seed[i]) * 0.0012;
520:         if (pos[i * 3 + 1] < 0.1) pos[i * 3 + 1] = 8.7;
521:         if (pos[i * 3 + 1] > 8.9) pos[i * 3 + 1] = 0.2;
522:       }
523:       this.dust.geometry.attributes.position.needsUpdate = true;
524:     }
525:     for (const l of this.lights) {
