.keycap { display: inline-flex; align-items: center; justify-content: center; width: 30px; height: 30px; border: 1px solid rgba(199,168,107,.55); color: var(--gold); font-family: var(--sans); font-size: 10px; letter-spacing: .1em; background: rgba(199,168,107,.07); }
